	private static <T> List<List<T>> pages(List<T> values, int entriesPerPage) {
		List<List<T>> pages = new ArrayList<>();
		for (int start = 0; start < values.size();) {
			int end = start + Math.min(entriesPerPage, values.size() - start);
			pages.add(values.subList(start, end));
			start = end;
		}
		return List.copyOf(pages);
	}
